import React, { useState } from "react";
import { Input } from "./ui/input";
import { Button } from "./ui/button";
import { Badge } from "./ui/badge";
import { DollarSign, Trophy, Calendar, Trash2 } from "lucide-react";

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;

export default function WinnersTab({ winners, fetchData }) {
  const [game, setGame] = useState("");
  const [amount, setAmount] = useState("");
  const [date, setDate] = useState("");
  const [file, setFile] = useState(null);
  const [photoUrl, setPhotoUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");

  // Sélection du fichier
  function onPick(e) {
    setFile(e.target.files?.[0] || null);
    setPhotoUrl(""); // Reset URL
  }

  // Upload image vers Hostinger
  async function uploadImageToHostinger(f, type) {
    const form = new FormData();
    form.append("type", type);
    form.append("file", f);

    const res = await fetch("https://triple7casino.ca/upload.php", {
      method: "POST",
      headers: {
        "X-ADMIN-KEY": "T7C-Admin-Only-2025!"
      },
      body: form
    });

    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Upload failed");
    return data.url;
  }

  // Handler Upload
  async function handleUpload() {
    if (!file) {
      setMsg("❌ Choisis un fichier d'abord");
      return;
    }
    try {
      setBusy(true);
      setMsg("⏳ Upload en cours...");
      const url = await uploadImageToHostinger(file, "winners");
      setPhotoUrl(url);
      setMsg("✅ Upload OK");
    } catch (e) {
      setMsg("❌ " + e.message);
    } finally {
      setBusy(false);
    }
  }

  // Ajouter gagnant
  async function handleAddWinner() {
    if (!photoUrl) {
      setMsg("⚠️ Fais l'upload de la photo d'abord.");
      return;
    }
    if (!game || !amount || !date) {
      setMsg("⚠️ Remplis tous les champs");
      return;
    }

    try {
      setBusy(true);
      setMsg("⏳ Ajout en cours...");
      const res = await fetch(BACKEND_URL + "/api/winners", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          game,
          amount: Number(amount),
          date,
          photo: photoUrl
        })
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || "Erreur API");

      setMsg("✅ Gagnant ajouté");
      // Reset
      setGame("");
      setAmount("");
      setDate("");
      setFile(null);
      setPhotoUrl("");
      fetchData();
    } catch (e) {
      setMsg("❌ " + e.message);
    } finally {
      setBusy(false);
    }
  }

  // Supprimer gagnant
  async function handleDeleteWinner(winnerId) {
    if (!window.confirm("Êtes-vous sûr de vouloir supprimer ce gagnant?")) {
      return;
    }

    try {
      const res = await fetch(`${BACKEND_URL}/api/winners/${winnerId}`, {
        method: "DELETE"
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || "Erreur suppression");
      setMsg("✅ Gagnant supprimé");
      fetchData();
    } catch (e) {
      setMsg("❌ " + e.message);
    }
  }

  const formatAmount = (amount) => {
    return new Intl.NumberFormat('fr-FR', {
      style: 'currency',
      currency: 'USD'
    }).format(amount).replace('$US', '$');
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleDateString("fr-FR");
  };

  return (
    <div className="space-y-6">
      {/* Formulaire d'ajout */}
      <div className="bg-black/50 rounded-lg p-6 border border-white/10">
        <h3 className="text-white font-bold text-xl mb-4">➕ Ajouter un gagnant</h3>

        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Input
              placeholder="Jeu (ex: Lightning Link)"
              value={game}
              onChange={(e) => setGame(e.target.value)}
              className="bg-black/50 border-white/20 text-white placeholder:text-white/50"
              required
            />
            <Input
              type="number"
              step="0.01"
              placeholder="Montant gagné ($)"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              className="bg-black/50 border-white/20 text-white placeholder:text-white/50"
              required
            />
            <Input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="bg-black/50 border-white/20 text-white"
              required
            />
          </div>

          {/* Upload image */}
          <div>
            <label className="block text-white/80 mb-2 text-sm font-semibold">
              📸 Photo du gagnant (obligatoire)
            </label>
            <div className="flex items-center gap-3">
              <Input
                type="file"
                accept="image/*"
                onChange={onPick}
                className="bg-black/50 border-white/20 text-white file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-yellow-500 file:text-black hover:file:bg-yellow-600 cursor-pointer"
              />
              <Button
                type="button"
                onClick={handleUpload}
                disabled={!file || busy}
                className="bg-blue-600 hover:bg-blue-700 text-white px-6 whitespace-nowrap"
              >
                {busy ? "Upload..." : "Upload"}
              </Button>
            </div>

            {photoUrl && (
              <div className="mt-3 bg-black/30 rounded-lg p-4 border border-white/10">
                <p className="text-green-400 text-sm mb-2">✅ Image uploadée</p>
                <img
                  src={photoUrl}
                  alt="preview"
                  className="w-40 h-40 object-cover rounded-lg border-2 border-yellow-500/50"
                />
              </div>
            )}
          </div>

          <Button
            onClick={handleAddWinner}
            disabled={busy || !photoUrl}
            className="w-full bg-gradient-to-r from-yellow-500 to-yellow-600 hover:from-yellow-600 hover:to-yellow-700 text-black font-bold"
          >
            Ajouter le gagnant
          </Button>

          {msg && (
            <div className="text-center text-sm text-white/80 bg-black/30 rounded p-2">
              {msg}
            </div>
          )}
        </div>
      </div>

      {/* Liste des gagnants */}
      <div className="bg-black/50 rounded-lg p-6 border border-white/10">
        <h3 className="text-white font-bold text-xl mb-4">🏆 Liste des gagnants</h3>

        {winners && winners.length > 0 ? (
          <div className="space-y-4">
            {winners.map((winner) => (
              <div
                key={winner.id}
                className="bg-black/50 rounded-lg p-4 border border-white/10 flex items-center justify-between gap-4"
              >
                {/* Photo */}
                <div className="flex-shrink-0">
                  <img
                    src={winner.photo}
                    alt="Gagnant"
                    className="w-24 h-24 object-cover rounded-lg border-2 border-yellow-500/50"
                    onError={(e) => {
                      e.target.src = "https://via.placeholder.com/150?text=Photo";
                    }}
                  />
                </div>

                {/* Infos */}
                <div className="flex-1 space-y-2">
                  <div className="flex items-center space-x-3 flex-wrap">
                    <Badge className="bg-green-600/20 text-green-400 text-base font-bold">
                      <DollarSign className="h-4 w-4 mr-1" />
                      {formatAmount(winner.amount)}
                    </Badge>
                    <Badge className="bg-yellow-600/20 text-yellow-400">
                      <Trophy className="h-3 w-3 mr-1" />
                      {winner.game}
                    </Badge>
                    <Badge className="bg-blue-600/20 text-blue-400">
                      <Calendar className="h-3 w-3 mr-1" />
                      {formatDate(winner.date)}
                    </Badge>
                  </div>
                </div>

                {/* Bouton supprimer */}
                <Button
                  onClick={() => handleDeleteWinner(winner.id)}
                  variant="outline"
                  size="sm"
                  className="border-red-500/50 text-red-400 hover:bg-red-500/20 flex-shrink-0"
                  title="Supprimer ce gagnant"
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-white/50 text-center py-8">Aucun gagnant pour le moment</p>
        )}
      </div>
    </div>
  );
}
