import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { 
  Gamepad2, 
  Spade, 
  Utensils, 
  Music, 
  Calendar, 
  Crown,
  Phone,
  Mail,
  Clock,
  Star,
  ArrowRight,
  X,
  ChevronLeft,
  ChevronRight,
  Info
} from 'lucide-react';
import { mockData } from '../mockData';
import { useLanguage } from '../context/LanguageContext';

const Services = () => {
  const { t } = useLanguage();
  
  // Fonction pour obtenir les traductions des services
  const getServiceTranslation = (serviceId) => {
    const serviceMap = {
      1: 'slots',
      2: 'tables', 
      3: 'events'
    };
    const key = serviceMap[serviceId];
    return key ? t(`services.${key}`) : null;
  };
  const [hoveredService, setHoveredService] = useState(null);
  const [selectedService, setSelectedService] = useState(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  // Images additionnelles pour chaque service
  const serviceImages = {
    1: [
      "https://images.unsplash.com/photo-1596838132731-3301c3fd4317?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1561133036-6e4ba62b8ef4?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&h=600&fit=crop"
    ],
    2: [
      "https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=800&h=600&fit=crop"
    ],
    3: [
      "https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1571068316344-75bc76f77890?w=800&h=600&fit=crop"
    ],
    4: [
      "https://images.unsplash.com/photo-1574391884720-bbc2f89684df?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1577971132647-f26d8ac5a514?w=800&h=600&fit=crop",
      "https://images.unsplash.com/photo-1579952363873-27d3bfad9c0d?w=800&h=600&fit=crop"
    ]
  };

  const getIcon = (iconName) => {
    const icons = {
      Gamepad2: Gamepad2,
      Spade: Spade,
      Utensils: Utensils,
      Music: Music,
      Calendar: Calendar,
      Crown: Crown
    };
    const IconComponent = icons[iconName];
    return IconComponent ? <IconComponent className="h-8 w-8" /> : <Gamepad2 className="h-8 w-8" />;
  };

  const scrollToContact = () => {
    const element = document.querySelector('#contact');
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const openServiceModal = (service) => {
    setSelectedService(service);
    setCurrentImageIndex(0);
  };

  const closeModal = () => {
    setSelectedService(null);
    setCurrentImageIndex(0);
  };

  const nextImage = () => {
    if (selectedService) {
      const images = serviceImages[selectedService.id] || [];
      setCurrentImageIndex((prev) => (prev + 1) % images.length);
    }
  };

  const prevImage = () => {
    if (selectedService) {
      const images = serviceImages[selectedService.id] || [];
      setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
    }
  };

  return (
    <section id="services" className="py-6 lg:py-12 bg-gradient-to-br from-black via-red-950/20 to-black">
      <div className="container mx-auto px-4">
        {/* Section Header Spectaculaire */}
        <div className="text-center mb-8">
          <div className="inline-block bg-gradient-to-r from-yellow-400 via-yellow-500 to-red-500 text-transparent bg-clip-text mb-6">
            <h2 className="text-5xl md:text-7xl font-black tracking-tight drop-shadow-2xl">
              🎯 {t('services.badge')} 🎯
            </h2>
          </div>
          <div className="mb-6">
            <span className="text-4xl md:text-6xl font-bold text-white drop-shadow-lg">
              {t('services.title')}
            </span>
          </div>
          <div className="h-2 w-40 bg-gradient-to-r from-yellow-400 to-red-500 mx-auto rounded-full mb-6"></div>
          <p className="text-xl md:text-2xl text-white font-bold max-w-4xl mx-auto drop-shadow-lg">
            {t('services.description')}
          </p>
        </div>

        {/* Services Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 mb-8">
          {mockData.services.map((service) => (
            <Card 
              key={service.id}
              className={`group bg-gradient-to-br from-black via-gray-900/90 to-black backdrop-blur-sm border-2 transition-all duration-500 cursor-pointer transform hover:scale-105 ${
                hoveredService === service.id 
                  ? 'border-yellow-400/60 shadow-2xl shadow-yellow-500/25' 
                  : 'border-red-500/30 hover:border-red-500/50'
              }`}
              onMouseEnter={() => setHoveredService(service.id)}
              onMouseLeave={() => setHoveredService(null)}
            >
              <CardHeader className="relative">
                {/* Service Image */}
                <div className="relative h-48 rounded-lg overflow-hidden mb-4">
                  <img 
                    src={service.image} 
                    alt={service.title}
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                  />
                  <div className="absolute inset-0 bg-black/60"></div>
                  
                  {/* Icon Overlay Amélioré */}
                  <div className="absolute top-4 right-4 p-4 bg-yellow-400 backdrop-blur-sm rounded-full border-2 border-yellow-300 shadow-lg">
                    <div className="text-black">
                      {getIcon(service.icon)}
                    </div>
                  </div>
                </div>

                {/* Title Amélioré */}
                <CardTitle className="text-2xl md:text-3xl font-black text-white mb-3 group-hover:text-yellow-400 transition-colors duration-300 drop-shadow-lg">
                  {getServiceTranslation(service.id)?.title || service.title}
                </CardTitle>
              </CardHeader>

              <CardContent className="space-y-4">
                {/* Description */}
                <p className="text-white/80 leading-relaxed">
                  {getServiceTranslation(service.id)?.description || service.description}
                </p>

                {/* Features Améliorées */}
                <div className="space-y-3">
                  <h4 className="text-yellow-400 font-black text-base uppercase tracking-wide drop-shadow-lg">
                    ⭐ {t('services.characteristics').toUpperCase()} ⭐
                  </h4>
                  <div className="grid grid-cols-1 gap-3">
                    {(getServiceTranslation(service.id)?.features || service.features).map((feature, index) => (
                      <div key={index} className="bg-gradient-to-r from-red-500/20 to-yellow-500/20 rounded-lg p-3 border border-yellow-500/30">
                        <div className="flex items-center space-x-3">
                          <div className="bg-yellow-400 rounded-full p-1">
                            <Star className="h-3 w-3 text-black" />
                          </div>
                          <span className="text-white font-medium text-sm">{feature}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Bouton Plus de détails */}
                <Button 
                  className="w-full bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-black text-lg px-6 py-3 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105 mt-4"
                  onClick={() => openServiceModal(service)}
                >
                  <Info className="h-5 w-5 mr-2" />
                  {t('services.moreDetails')}
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* CTA Section */}
        <div className="text-center mt-8">
          <p className="text-2xl md:text-3xl text-white font-bold mb-6 drop-shadow-lg">
            {t('services.readyForExperience')}
          </p>
          <div className="flex flex-col sm:flex-row gap-6 justify-center">
            <Button 
              className="bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-black text-xl px-12 py-6 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105"
              onClick={scrollToContact}
            >
              <Phone className="h-5 w-5 mr-2" />
              📞 {t('services.reserveNow')}
            </Button>
            <Button 
              variant="outline"
              className="bg-transparent border-2 border-yellow-400 text-yellow-400 hover:bg-yellow-400 hover:text-black font-black text-xl px-12 py-6 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105 backdrop-blur-sm"
              onClick={scrollToContact}
            >
              <Mail className="h-5 w-5 mr-2" />
              {t('services.contactUs')}
            </Button>
          </div>
        </div>

        {/* Modal Pop-up pour les détails du service */}
        {selectedService && (
          <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-gradient-to-br from-black via-gray-900 to-black rounded-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden border-2 border-yellow-500/30 shadow-2xl">
              
              {/* Header Modal */}
              <div className="flex justify-between items-center p-6 border-b border-white/10">
                <h3 className="text-2xl md:text-3xl font-black text-white">
                  🎲 {selectedService.title}
                </h3>
                <Button
                  onClick={closeModal}
                  className="bg-red-600/20 hover:bg-red-600/40 text-red-400 border-2 border-red-500/30 rounded-full p-2"
                >
                  <X className="h-6 w-6" />
                </Button>
              </div>

              {/* Content Modal */}
              <div className="p-6 max-h-[70vh] overflow-y-auto">
                
                {/* Image Carousel */}
                <div className="relative mb-8">
                  <div className="relative h-64 md:h-80 rounded-xl overflow-hidden">
                    <img 
                      src={serviceImages[selectedService.id]?.[currentImageIndex] || selectedService.image}
                      alt={`${selectedService.title} - Image ${currentImageIndex + 1}`}
                      className="w-full h-full object-cover transition-transform duration-300"
                    />
                    
                    {/* Navigation Images */}
                    {serviceImages[selectedService.id]?.length > 1 && (
                      <>
                        <Button
                          onClick={prevImage}
                          className="absolute left-4 top-1/2 transform -translate-y-1/2 bg-black/60 hover:bg-black/80 text-white border-0 rounded-full p-2"
                        >
                          <ChevronLeft className="h-6 w-6" />
                        </Button>
                        <Button
                          onClick={nextImage}
                          className="absolute right-4 top-1/2 transform -translate-y-1/2 bg-black/60 hover:bg-black/80 text-white border-0 rounded-full p-2"
                        >
                          <ChevronRight className="h-6 w-6" />
                        </Button>
                      </>
                    )}

                    {/* Indicateurs d'images */}
                    {serviceImages[selectedService.id]?.length > 1 && (
                      <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex space-x-2">
                        {serviceImages[selectedService.id].map((_, index) => (
                          <button
                            key={index}
                            onClick={() => setCurrentImageIndex(index)}
                            className={`w-3 h-3 rounded-full transition-all duration-300 ${
                              index === currentImageIndex 
                                ? 'bg-yellow-400 scale-125' 
                                : 'bg-white/50 hover:bg-white/70'
                            }`}
                          />
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Service Details */}
                <div className="space-y-6">
                  <div>
                    <h4 className="text-xl font-black text-yellow-400 mb-3 drop-shadow-lg">
                      📋 Description Complète
                    </h4>
                    <p className="text-white/90 font-medium text-lg leading-relaxed">
                      {selectedService.description}
                    </p>
                  </div>

                  <div>
                    <h4 className="text-xl font-black text-yellow-400 mb-3 drop-shadow-lg">
                      ⭐ {t('services.premiumCharacteristics')}
                    </h4>
                    <div className="grid grid-cols-1 gap-3">
                      {(getServiceTranslation(selectedService.id)?.features || selectedService.features).map((feature, index) => (
                        <div key={index} className="bg-gradient-to-r from-red-500/20 to-yellow-500/20 rounded-lg p-4 border border-yellow-500/30">
                          <div className="flex items-center space-x-3">
                            <div className="bg-yellow-400 rounded-full p-2">
                              <Star className="h-4 w-4 text-black" />
                            </div>
                            <span className="text-white font-bold">{feature}</span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* CTA Modal */}
                  <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t border-white/10">
                    <Button 
                      className="flex-1 bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-black text-lg px-8 py-4 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105"
                      onClick={() => {
                        closeModal();
                        scrollToContact();
                      }}
                    >
                      <Phone className="h-5 w-5 mr-2" />
                      📞 {t('services.reserveService')}
                    </Button>
                    <Button 
                      variant="outline"
                      className="flex-1 bg-transparent border-2 border-yellow-400 text-yellow-400 hover:bg-yellow-400 hover:text-black font-black text-lg px-8 py-4 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105 backdrop-blur-sm"
                      onClick={closeModal}
                    >
                      👁️ Continuer à Explorer
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

export default Services;