import React, { useState, useEffect } from 'react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Calendar, Percent, DollarSign, Tag, Info, X } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';
import axios from 'axios';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;

const Promotions = () => {
  const { t } = useLanguage();
  const [promotions, setPromotions] = useState([]);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [selectedPromo, setSelectedPromo] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  // Charger les promotions depuis l'API
  useEffect(() => {
    const fetchPromotions = async () => {
      try {
        const response = await axios.get(`${BACKEND_URL}/api/promotions`);
        setPromotions(response.data.promotions || []);
      } catch (error) {
        console.error('Error fetching promotions:', error);
        setPromotions([]);
      } finally {
        setIsLoading(false);
      }
    };

    fetchPromotions();
  }, []);

  // Auto-play carousel
  useEffect(() => {
    if (promotions.length === 0) return;
    
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % promotions.length);
    }, 5000);

    return () => clearInterval(interval);
  }, [promotions.length]);

  const formatDate = (dateStr) => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('fr-FR', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
  };

  if (isLoading) {
    return (
      <section className="py-6 lg:py-12 bg-gradient-to-br from-black via-gray-900 to-black">
        <div className="container mx-auto px-4 text-center">
          <p className="text-white text-xl">Chargement des promotions...</p>
        </div>
      </section>
    );
  }

  if (promotions.length === 0) {
    return null; // Ne rien afficher si pas de promotions
  }

  return (
    <section id="promotions" className="py-6 lg:py-12 bg-gradient-to-br from-black via-purple-950/20 to-black relative overflow-hidden">
      <div className="container mx-auto px-4 relative z-10">
        {/* Section Header */}
        <div className="text-center mb-8">
          <div className="inline-block mb-4">
            <Badge className="bg-gradient-to-r from-purple-600 to-pink-600 text-white px-6 py-2 text-sm font-bold uppercase tracking-wider border-0 shadow-lg">
              🎁 PROMOTIONS EXCLUSIVES
            </Badge>
          </div>
          <h2 className="text-4xl lg:text-5xl font-black text-transparent bg-gradient-to-r from-purple-400 via-pink-400 to-red-400 bg-clip-text mb-6">
            Offres Spéciales
          </h2>
          <p className="text-white/80 text-lg max-w-3xl mx-auto">
            Profitez de nos promotions exceptionnelles et maximisez vos gains
          </p>
        </div>

        {/* Promotions Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {promotions.map((promo) => (
            <Card 
              key={promo.id}
              className="bg-gradient-to-br from-black/90 via-purple-950/50 to-black/90 backdrop-blur-sm border-2 border-purple-500/30 hover:border-purple-400/60 transition-all duration-300 transform hover:scale-105 shadow-2xl hover:shadow-purple-500/20 cursor-pointer"
              onClick={() => setSelectedPromo(promo)}
            >
              <CardContent className="p-0">
                {/* Image */}
                <div className="relative h-48 overflow-hidden rounded-t-lg">
                  <img 
                    src={promo.image_url} 
                    alt={promo.title}
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      e.target.src = 'https://images.unsplash.com/photo-1557683316-973673baf926?w=400&h=300&fit=crop';
                    }}
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent" />
                  
                  {/* Badge promo code */}
                  {promo.promo_code && (
                    <div className="absolute top-4 right-4">
                      <Badge className="bg-yellow-400 text-black font-bold px-3 py-1">
                        <Tag className="h-3 w-3 mr-1" />
                        {promo.promo_code}
                      </Badge>
                    </div>
                  )}
                </div>

                {/* Content */}
                <div className="p-6">
                  <h3 className="text-2xl font-bold text-white mb-3">
                    {promo.title}
                  </h3>
                  
                  <p className="text-white/70 mb-4 line-clamp-2">
                    {promo.description}
                  </p>

                  {/* Promo Details */}
                  <div className="space-y-2 mb-4">
                    {promo.percent_off && (
                      <div className="flex items-center space-x-2 text-green-400">
                        <Percent className="h-4 w-4" />
                        <span className="font-bold text-lg">{promo.percent_off}% de réduction</span>
                      </div>
                    )}
                    
                    {promo.fixed_amount && (
                      <div className="flex items-center space-x-2 text-yellow-400">
                        <DollarSign className="h-4 w-4" />
                        <span className="font-bold text-lg">{promo.fixed_amount}$ offerts</span>
                      </div>
                    )}

                    <div className="flex items-center space-x-2 text-white/60 text-sm">
                      <Calendar className="h-4 w-4" />
                      <span>
                        Valide du {formatDate(promo.start_date)} au {formatDate(promo.end_date)}
                      </span>
                    </div>
                  </div>

                  {/* Button */}
                  <button 
                    className="w-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-bold py-3 rounded-lg transition-all duration-300 shadow-lg hover:shadow-purple-500/50"
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedPromo(promo);
                    }}
                  >
                    <Info className="inline h-4 w-4 mr-2" />
                    Voir les détails
                  </button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>

      {/* Modal Détails Promotion */}
      {selectedPromo && (
        <div 
          className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4"
          onClick={() => setSelectedPromo(null)}
        >
          <div 
            className="bg-gradient-to-br from-black via-purple-950/90 to-black border-2 border-purple-500/40 rounded-2xl max-w-2xl w-full mx-auto overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Close Button */}
            <div className="flex justify-end p-4">
              <button
                onClick={() => setSelectedPromo(null)}
                className="text-white/60 hover:text-white transition-colors"
              >
                <X className="h-6 w-6" />
              </button>
            </div>

            {/* Image */}
            <div className="relative h-64 -mt-16">
              <img 
                src={selectedPromo.image_url} 
                alt={selectedPromo.title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent" />
            </div>

            {/* Content */}
            <div className="p-8">
              {/* Promo Code Badge */}
              {selectedPromo.promo_code && (
                <div className="mb-6 text-center">
                  <p className="text-white/60 text-sm mb-2">Code promo:</p>
                  <div className="inline-block bg-yellow-400 text-black font-bold text-2xl px-6 py-3 rounded-lg">
                    {selectedPromo.promo_code}
                  </div>
                </div>
              )}

              <h2 className="text-3xl font-black text-transparent bg-gradient-to-r from-purple-400 to-pink-400 bg-clip-text mb-4">
                {selectedPromo.title}
              </h2>

              <p className="text-white/80 text-lg mb-6">
                {selectedPromo.description}
              </p>

              {/* Promo Details */}
              <div className="bg-gradient-to-r from-purple-500/20 to-pink-500/20 rounded-lg p-6 mb-6 space-y-3">
                {selectedPromo.percent_off && (
                  <div className="flex items-center justify-between">
                    <span className="text-white/70">Réduction:</span>
                    <span className="text-green-400 font-bold text-xl">
                      <Percent className="inline h-5 w-5 mr-1" />
                      {selectedPromo.percent_off}%
                    </span>
                  </div>
                )}
                
                {selectedPromo.fixed_amount && (
                  <div className="flex items-center justify-between">
                    <span className="text-white/70">Montant offert:</span>
                    <span className="text-yellow-400 font-bold text-xl">
                      <DollarSign className="inline h-5 w-5 mr-1" />
                      {selectedPromo.fixed_amount}$
                    </span>
                  </div>
                )}

                <div className="flex items-center justify-between">
                  <span className="text-white/70">Période de validité:</span>
                  <span className="text-white font-medium">
                    {formatDate(selectedPromo.start_date)} - {formatDate(selectedPromo.end_date)}
                  </span>
                </div>
              </div>

              {/* CTA */}
              <button 
                className="w-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-black text-lg px-8 py-4 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105"
                onClick={() => {
                  const element = document.querySelector('#contact');
                  if (element) {
                    element.scrollIntoView({ behavior: 'smooth' });
                  }
                  setSelectedPromo(null);
                }}
              >
                🎁 Profiter de cette offre
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Background decoration */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-1/4 -left-32 w-96 h-96 bg-purple-600/10 rounded-full blur-3xl"></div>
        <div className="absolute bottom-1/4 -right-32 w-96 h-96 bg-pink-600/10 rounded-full blur-3xl"></div>
      </div>
    </section>
  );
};

export default Promotions;
