import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { Badge } from './ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import { 
  LogOut, 
  Trophy, 
  Settings, 
  Plus, 
  Edit, 
  Trash2, 
  DollarSign,
  Calendar,
  User,
  Mail,
  CheckCircle,
  XCircle,
  MessageSquare
} from 'lucide-react';
import { EventsTab, PromotionsTab } from './AdminTabs';
import WinnersTab from './WinnersTab';
import axios from 'axios';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;

const AdminDashboard = ({ onLogout }) => {
  const [winners, setWinners] = useState([]);
  const [contactMessages, setContactMessages] = useState([]);
  const [reservations, setReservations] = useState([]);
  const [events, setEvents] = useState([]);
  const [promotions, setPromotions] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [newWinner, setNewWinner] = useState({
    amount: '',
    game: '',
    date: new Date().toISOString().split('T')[0],
    photo: ''
  });
  const [selectedFile, setSelectedFile] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadPreview, setUploadPreview] = useState(null);
  const [newEvent, setNewEvent] = useState({
    title: '',
    description: '',
    date: new Date().toISOString().split('T')[0],
    time: '',
    price: '',
    image: '',
    category: 'general'
  });
  const [newPromotion, setNewPromotion] = useState({
    title: '',
    description: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0],
    discountPercent: '',
    discountAmount: '',
    code: '',
    image: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [winnersRes, contactRes, reservationsRes, eventsRes, promotionsRes] = await Promise.all([
        axios.get(`${BACKEND_URL}/api/winners`),
        axios.get(`${BACKEND_URL}/api/contact`),
        axios.get(`${BACKEND_URL}/api/reservations`),
        axios.get(`${BACKEND_URL}/api/events`),
        axios.get(`${BACKEND_URL}/api/promotions`)
      ]);

      setWinners(winnersRes.data.winners || []);
      setContactMessages(contactRes.data.messages || []);
      setReservations(reservationsRes.data.reservations || []);
      setEvents(eventsRes.data.events || []);
      setPromotions(promotionsRes.data.promotions || []);
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      setSelectedFile(file);
      // Create preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUploadImage = async () => {
    if (!selectedFile) {
      alert('Veuillez sélectionner une image');
      return;
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', selectedFile);

      const response = await axios.post(`${BACKEND_URL}/api/upload`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        }
      });

      // Set the uploaded URL
      setNewWinner({...newWinner, photo: `${BACKEND_URL}${response.data.url}`});
      alert('✅ Image uploadée avec succès!');
    } catch (error) {
      console.error('Error uploading image:', error);
      alert('❌ Erreur lors de l\'upload de l\'image');
    } finally {
      setIsUploading(false);
    }
  };

  const handleAddWinner = async (e) => {
    e.preventDefault();
    
    if (!newWinner.photo) {
      alert('⚠️ Veuillez uploader une photo du gagnant');
      return;
    }

    try {
      const winnerData = {
        ...newWinner,
        amount: parseFloat(newWinner.amount),
        date: new Date(newWinner.date).toISOString()
      };

      await axios.post(`${BACKEND_URL}/api/winners`, winnerData);
      
      setNewWinner({
        amount: '',
        game: '',
        date: new Date().toISOString().split('T')[0],
        photo: ''
      });
      setSelectedFile(null);
      setUploadPreview(null);
      
      alert('✅ Gagnant ajouté avec succès!');
      fetchData(); // Refresh data
    } catch (error) {
      console.error('Error adding winner:', error);
      alert('❌ Erreur lors de l\'ajout du gagnant');
    }
  };

  const handleDeleteWinner = async (winnerId) => {
    if (!window.confirm('Êtes-vous sûr de vouloir supprimer ce gagnant?')) {
      return;
    }
    
    try {
      await axios.delete(`${BACKEND_URL}/api/winners/${winnerId}`);
      alert('✅ Gagnant supprimé avec succès!');
      fetchData(); // Refresh data
    } catch (error) {
      console.error('Error deleting winner:', error);
      alert('❌ Erreur lors de la suppression du gagnant');
    }
  };

  const handleAddEvent = async (e) => {
    e.preventDefault();
    try {
      const eventData = {
        ...newEvent,
        price: newEvent.price ? parseFloat(newEvent.price) : null
      };

      await axios.post(`${BACKEND_URL}/api/events`, eventData);
      
      setNewEvent({
        title: '',
        description: '',
        date: new Date().toISOString().split('T')[0],
        time: '',
        price: '',
        image: '',
        category: 'general'
      });
      
      fetchData();
    } catch (error) {
      console.error('Error adding event:', error);
    }
  };

  const handleAddPromotion = async (e) => {
    e.preventDefault();
    try {
      const promotionData = {
        ...newPromotion,
        discountPercent: newPromotion.discountPercent ? parseInt(newPromotion.discountPercent) : null,
        discountAmount: newPromotion.discountAmount ? parseFloat(newPromotion.discountAmount) : null
      };

      await axios.post(`${BACKEND_URL}/api/promotions`, promotionData);
      
      setNewPromotion({
        title: '',
        description: '',
        startDate: new Date().toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        discountPercent: '',
        discountAmount: '',
        code: '',
        image: ''
      });
      
      fetchData();
    } catch (error) {
      console.error('Error adding promotion:', error);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('adminAuth');
    onLogout(false);
  };

  const formatAmount = (amount) => {
    return new Intl.NumberFormat('fr-CA', {
      style: 'currency',
      currency: 'CAD'
    }).format(amount);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('fr-CA');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-red-950/20 to-black p-4">
      {/* Header */}
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold text-transparent bg-gradient-to-r from-yellow-400 to-red-500 bg-clip-text">
            Administration Casino TRIPLE 7
          </h1>
          <p className="text-white/70">Tableau de bord administrateur</p>
        </div>
        <Button 
          onClick={handleLogout}
          variant="outline"
          className="border-red-500/50 text-red-400 hover:bg-red-500/20"
        >
          <LogOut className="h-4 w-4 mr-2" />
          Déconnexion
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-black/80 via-yellow-950/40 to-black/80 border border-yellow-500/20">
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <Trophy className="h-8 w-8 text-yellow-400" />
              <div>
                <p className="text-yellow-400 font-semibold">Gagnants</p>
                <p className="text-2xl text-white font-bold">{winners.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-gradient-to-br from-black/80 via-red-950/40 to-black/80 border border-red-500/20">
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <MessageSquare className="h-8 w-8 text-red-400" />
              <div>
                <p className="text-red-400 font-semibold">Messages</p>
                <p className="text-2xl text-white font-bold">{contactMessages.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-gradient-to-br from-black/80 via-green-950/40 to-black/80 border border-green-500/20">
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <Calendar className="h-8 w-8 text-green-400" />
              <div>
                <p className="text-green-400 font-semibold">Réservations</p>
                <p className="text-2xl text-white font-bold">{reservations.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-gradient-to-br from-black/80 via-blue-950/40 to-black/80 border border-blue-500/20">
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <Calendar className="h-8 w-8 text-blue-400" />
              <div>
                <p className="text-blue-400 font-semibold">Événements</p>
                <p className="text-2xl text-white font-bold">{events.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-gradient-to-br from-black/80 via-purple-950/40 to-black/80 border border-purple-500/20">
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <CheckCircle className="h-8 w-8 text-purple-400" />
              <div>
                <p className="text-purple-400 font-semibold">Promotions</p>
                <p className="text-2xl text-white font-bold">{promotions.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs defaultValue="winners" className="space-y-6">
        <TabsList className="bg-black/50 border border-white/20">
          <TabsTrigger value="winners" className="data-[state=active]:bg-yellow-600/20 data-[state=active]:text-yellow-400">
            <Trophy className="h-4 w-4 mr-2" />
            Gagnants
          </TabsTrigger>
          <TabsTrigger value="messages" className="data-[state=active]:bg-red-600/20 data-[state=active]:text-red-400">
            <MessageSquare className="h-4 w-4 mr-2" />
            Messages
          </TabsTrigger>
          <TabsTrigger value="reservations" className="data-[state=active]:bg-green-600/20 data-[state=active]:text-green-400">
            <Calendar className="h-4 w-4 mr-2" />
            Réservations
          </TabsTrigger>
          <TabsTrigger value="events" className="data-[state=active]:bg-blue-600/20 data-[state=active]:text-blue-400">
            <Calendar className="h-4 w-4 mr-2" />
            Événements
          </TabsTrigger>
          <TabsTrigger value="promotions" className="data-[state=active]:bg-purple-600/20 data-[state=active]:text-purple-400">
            <CheckCircle className="h-4 w-4 mr-2" />
            Promotions
          </TabsTrigger>
        </TabsList>

        {/* Winners Tab */}
        <TabsContent value="winners" className="space-y-6">
          <WinnersTab winners={winners} fetchData={fetchData} />
          {/* Add New Winner Form */}
          <Card className="bg-gradient-to-br from-black/80 via-yellow-950/40 to-black/80 border border-yellow-500/20">
            <CardHeader>
              <CardTitle className="text-white flex items-center space-x-2">
                <Plus className="h-5 w-5 text-yellow-400" />
                <span>Ajouter un nouveau gagnant</span>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleAddWinner} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <Input
                    placeholder="Jeu (ex: Lightning Link)"
                    value={newWinner.game}
                    onChange={(e) => setNewWinner({...newWinner, game: e.target.value})}
                    className="bg-black/50 border-white/20 text-white placeholder:text-white/50"
                    required
                  />
                  <Input
                    type="number"
                    step="0.01"
                    placeholder="Montant gagné ($)"
                    value={newWinner.amount}
                    onChange={(e) => setNewWinner({...newWinner, amount: e.target.value})}
                    className="bg-black/50 border-white/20 text-white placeholder:text-white/50"
                    required
                  />
                  <Input
                    type="date"
                    value={newWinner.date}
                    onChange={(e) => setNewWinner({...newWinner, date: e.target.value})}
                    className="bg-black/50 border-white/20 text-white"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-white/80 mb-2 text-sm font-semibold">
                    📸 Photo du gagnant (obligatoire)
                  </label>
                  
                  <div className="space-y-3">
                    {/* File input */}
                    <div className="flex items-center gap-3">
                      <Input
                        type="file"
                        accept="image/jpeg,image/jpg,image/png,image/webp"
                        onChange={handleFileSelect}
                        className="bg-black/50 border-white/20 text-white file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-yellow-500 file:text-black hover:file:bg-yellow-600 cursor-pointer"
                      />
                      <Button
                        type="button"
                        onClick={handleUploadImage}
                        disabled={!selectedFile || isUploading}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 whitespace-nowrap"
                      >
                        {isUploading ? 'Upload en cours...' : 'Upload'}
                      </Button>
                    </div>

                    {/* Preview */}
                    {(uploadPreview || newWinner.photo) && (
                      <div className="bg-black/30 rounded-lg p-4 border border-white/10">
                        <p className="text-white/60 text-xs mb-2">Aperçu:</p>
                        <img 
                          src={uploadPreview || newWinner.photo} 
                          alt="Aperçu" 
                          className="w-40 h-40 object-cover rounded-lg border-2 border-yellow-500/50 shadow-lg"
                        />
                        {newWinner.photo && (
                          <p className="text-green-400 text-xs mt-2 flex items-center">
                            <CheckCircle className="h-3 w-3 mr-1" />
                            Image uploadée avec succès
                          </p>
                        )}
                      </div>
                    )}

                    <p className="text-white/50 text-xs">
                      💡 Formats acceptés: JPG, PNG, WEBP (max 5MB)
                    </p>
                  </div>
                </div>
                
                <Button 
                  type="submit"
                  className="w-full bg-gradient-to-r from-yellow-500 to-yellow-600 hover:from-yellow-600 hover:to-yellow-700 text-black font-bold"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Ajouter le gagnant
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Winners List */}
          <Card className="bg-gradient-to-br from-black/80 via-red-950/40 to-black/80 border border-red-500/20">
            <CardHeader>
              <CardTitle className="text-white">Liste des gagnants</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {winners.map((winner) => (
                  <div key={winner.id} className="bg-black/50 rounded-lg p-4 border border-white/10">
                    <div className="flex items-center justify-between gap-4">
                      {/* Photo du gagnant */}
                      <div className="flex-shrink-0">
                        <img 
                          src={winner.photo} 
                          alt="Gagnant" 
                          className="w-24 h-24 object-cover rounded-lg border-2 border-yellow-500/50"
                          onError={(e) => {
                            e.target.src = 'https://via.placeholder.com/150?text=Photo';
                          }}
                        />
                      </div>
                      
                      {/* Informations du gagnant */}
                      <div className="flex-1 space-y-2">
                        <div className="flex items-center space-x-3 flex-wrap">
                          <Badge className="bg-green-600/20 text-green-400 text-base font-bold">
                            <DollarSign className="h-4 w-4 mr-1" />
                            {formatAmount(winner.amount)}
                          </Badge>
                          <Badge className="bg-yellow-600/20 text-yellow-400">
                            <Trophy className="h-3 w-3 mr-1" />
                            {winner.game}
                          </Badge>
                          <Badge className="bg-blue-600/20 text-blue-400">
                            <Calendar className="h-3 w-3 mr-1" />
                            {formatDate(winner.date)}
                          </Badge>
                        </div>
                      </div>
                      
                      {/* Bouton supprimer */}
                      <Button
                        onClick={() => handleDeleteWinner(winner.id)}
                        variant="outline"
                        size="sm"
                        className="border-red-500/50 text-red-400 hover:bg-red-500/20 flex-shrink-0"
                        title="Supprimer ce gagnant"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Messages Tab */}
        <TabsContent value="messages" className="space-y-6">
          <Card className="bg-gradient-to-br from-black/80 via-red-950/40 to-black/80 border border-red-500/20">
            <CardHeader>
              <CardTitle className="text-white">Messages de contact</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {contactMessages.map((message) => (
                  <div key={message.id} className="bg-black/50 rounded-lg p-4 border border-white/10">
                    <div className="space-y-3">
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="text-white font-semibold">{message.name}</h3>
                          <p className="text-white/70">{message.email}</p>
                          {message.phone && <p className="text-white/70">{message.phone}</p>}
                        </div>
                        <Badge className={message.status === 'new' ? 'bg-yellow-600/20 text-yellow-400' : 'bg-green-600/20 text-green-400'}>
                          {message.status === 'new' ? 'Nouveau' : 'Traité'}
                        </Badge>
                      </div>
                      {message.service && (
                        <p className="text-blue-400 text-sm">Service: {message.service}</p>
                      )}
                      <p className="text-white/80">{message.message}</p>
                      <p className="text-white/50 text-sm">{formatDate(message.createdAt)}</p>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Reservations Tab */}
        <TabsContent value="reservations" className="space-y-6">
          <Card className="bg-gradient-to-br from-black/80 via-green-950/40 to-black/80 border border-green-500/20">
            <CardHeader>
              <CardTitle className="text-white">Réservations</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {reservations.map((reservation) => (
                  <div key={reservation.id} className="bg-black/50 rounded-lg p-4 border border-white/10">
                    <div className="space-y-3">
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="text-white font-semibold">{reservation.name}</h3>
                          <p className="text-white/70">{reservation.email}</p>
                          <p className="text-white/70">{reservation.phone}</p>
                        </div>
                        <Badge className={reservation.status === 'pending' ? 'bg-yellow-600/20 text-yellow-400' : 'bg-green-600/20 text-green-400'}>
                          {reservation.status === 'pending' ? 'En attente' : 'Confirmé'}
                        </Badge>
                      </div>
                      <div className="grid grid-cols-2 gap-4 text-sm">
                        <div>
                          <span className="text-white/50">Service:</span>
                          <span className="text-white ml-2">{reservation.service}</span>
                        </div>
                        {reservation.partySize && (
                          <div>
                            <span className="text-white/50">Personnes:</span>
                            <span className="text-white ml-2">{reservation.partySize}</span>
                          </div>
                        )}
                        {reservation.preferredDate && (
                          <div>
                            <span className="text-white/50">Date souhaitée:</span>
                            <span className="text-white ml-2">{formatDate(reservation.preferredDate)}</span>
                          </div>
                        )}
                        {reservation.preferredTime && (
                          <div>
                            <span className="text-white/50">Heure:</span>
                            <span className="text-white ml-2">{reservation.preferredTime}</span>
                          </div>
                        )}
                      </div>
                      {reservation.message && (
                        <p className="text-white/80">{reservation.message}</p>
                      )}
                      <p className="text-white/50 text-sm">{formatDate(reservation.createdAt)}</p>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Events Tab */}
        <TabsContent value="events" className="space-y-6">
          <EventsTab 
            events={events}
            newEvent={newEvent}
            setNewEvent={setNewEvent}
            handleAddEvent={handleAddEvent}
          />
        </TabsContent>

        {/* Promotions Tab */}
        <TabsContent value="promotions" className="space-y-6">
          <PromotionsTab 
            promotions={promotions}
            newPromotion={newPromotion}
            setNewPromotion={setNewPromotion}
            handleAddPromotion={handleAddPromotion}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default AdminDashboard;