import React, { useState } from 'react';
import { Button } from './ui/button';
import { Sheet, SheetContent, SheetTrigger } from './ui/sheet';
import { Menu, MapPin, Phone, ArrowRight } from 'lucide-react';
import { mockData } from '../mockData';
import { useLanguage } from '../context/LanguageContext';
import LanguageSelector from './LanguageSelector';

const Header = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { t } = useLanguage();

  const scrollToSection = (href) => {
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
      setIsMobileMenuOpen(false);
    }
  };

  const openLocation = () => {
    // Desktop : nouveau lien
    const desktopLink = 'https://maps.app.goo.gl/agkh9UEyLuUxCpZc7';
    // Mobile : ancien lien conservé
    const mobileLink = 'https://maps.app.goo.gl/vyW424Y7rv1wbiaU7';
    
    // Détecter si c'est desktop ou mobile
    const isDesktop = window.innerWidth >= 1024; // lg breakpoint
    const linkToOpen = isDesktop ? desktopLink : mobileLink;
    
    window.open(linkToOpen, '_blank');
  };

  const navigation = [
    { 
      id: 'accueil', 
      label: t('nav.home'),
      hasDropdown: false,
      href: '#hero'
    },
    { 
      id: 'promotions', 
      label: t('nav.promotions'),
      hasDropdown: false,
      href: '#promotions'
    },
    { 
      id: 'services', 
      label: t('nav.services'),
      hasDropdown: false,
      href: '#services'
    },
    { 
      id: 'winners', 
      label: t('nav.winners'),
      hasDropdown: false,
      href: '#winners'
    },
    { 
      id: 'contact', 
      label: t('nav.contact'),
      hasDropdown: false,
      href: '#contact'
    }
  ];

  return (
    <>
    {/* Header Desktop avec Menu Transparent */}
    <header className="fixed top-0 left-0 right-0 z-50 bg-black/90 backdrop-blur-lg border-b border-white/10 hidden lg:block h-24">
      <div className="container mx-auto px-6 h-full flex items-center">
        {/* VERSION DESKTOP - Layout équilibré avec logo centré parfaitement */}
        <div className="w-full flex items-center justify-between">
          {/* Navigation à gauche avec distance calculée */}
          <div className="flex justify-start">
            <nav className="flex items-center space-x-6 bg-black/60 backdrop-blur-sm px-6 py-2 rounded-sm">
              {navigation.map((item) => (
                <button
                  key={item.id}
                  onClick={() => scrollToSection(item.href)}
                  className="text-white hover:text-yellow-400 transition-colors duration-300 font-medium text-base tracking-wide uppercase"
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          {/* Logo au centre parfait - Position absolue pour vraie centrage */}
          <div className="absolute left-1/2 transform -translate-x-1/2">
            <img 
              src="https://customer-assets.emergentagent.com/job_bfcf573f-3f35-45ed-8482-517185aee71f/artifacts/89y4fcq0_Untitled%20design%20%281%29.png" 
              alt="TRIPLE 7 Casino" 
              className="h-32 w-auto"
            />
          </div>

          {/* Utilities à droite */}
          <div className="flex justify-end">
            <div className="flex items-center space-x-1 bg-white/20 backdrop-blur-sm px-4 py-2 rounded-sm">
              <LanguageSelector />
              <div className="w-px h-6 bg-white/20 mx-2"></div>
              <Button 
                onClick={() => scrollToSection('#contact')}
                className="bg-transparent hover:bg-white/10 text-white text-sm font-medium px-3 py-2 h-auto flex items-center space-x-2 transition-all duration-300"
              >
                <ArrowRight className="h-4 w-4" />
                <span>{t('nav.reserve')}</span>
              </Button>
              <Button 
                onClick={openLocation}
                className="bg-transparent hover:bg-white/10 text-white text-sm font-medium px-3 py-2 h-auto flex items-center space-x-2 transition-all duration-300"
              >
                <MapPin className="h-4 w-4" />
                <span>{t('nav.visit')}</span>
              </Button>
            </div>
          </div>
        </div>
      </div>
    </header>
    
    {/* Header Mobile avec nouvelle structure */}
    <header className="fixed top-0 left-0 right-0 z-50 bg-black/90 backdrop-blur-lg border-b border-white/10 lg:hidden h-20">
      <div className="container mx-auto px-4 h-full">
        <div className="flex items-center justify-between h-full">
          {/* Bouton Visite à gauche */}
          <Button 
            onClick={openLocation}
            className="bg-yellow-500 hover:bg-yellow-600 text-black font-bold px-4 py-2 rounded-lg shadow-lg flex items-center space-x-2 transition-all duration-300"
          >
            <MapPin className="h-5 w-5" />
            <span>{t('nav.visit')}</span>
          </Button>

          {/* Logo centré */}
          <div className="absolute left-1/2 transform -translate-x-1/2">
            <img 
              src="https://customer-assets.emergentagent.com/job_bfcf573f-3f35-45ed-8482-517185aee71f/artifacts/89y4fcq0_Untitled%20design%20%281%29.png" 
              alt="TRIPLE 7 Casino" 
              className="h-16 w-auto"
            />
          </div>

          {/* Bouton Menu à droite */}
          <Sheet open={isMobileMenuOpen} onOpenChange={setIsMobileMenuOpen}>
            <SheetTrigger asChild>
              <Button
                className="bg-red-600 hover:bg-red-700 text-white font-bold px-4 py-2 rounded-lg shadow-lg flex items-center space-x-2 transition-all duration-300"
              >
                <Menu className="h-5 w-5" />
                <span>Menu</span>
              </Button>
            </SheetTrigger>
            <SheetContent side="right" className="w-80 bg-black/95 backdrop-blur-md border-red-600/20">
              <div className="flex flex-col space-y-6 mt-8">
                {/* Logo dans le menu */}
                <div className="text-center">
                  <img 
                    src="https://customer-assets.emergentagent.com/job_bfcf573f-3f35-45ed-8482-517185aee71f/artifacts/89y4fcq0_Untitled%20design%20%281%29.png" 
                    alt="TRIPLE 7 Casino" 
                    className="h-16 w-auto mx-auto mb-4"
                  />
                  <p className="text-yellow-300/80">Casino • Oka, Québec</p>
                </div>

                {/* Sélecteur de langue dans le menu */}
                <div className="flex justify-center">
                  <LanguageSelector />
                </div>
                
                {/* Navigation Mobile One-Page */}
                <nav className="flex flex-col space-y-4">
                  {navigation.map((item) => (
                    <button
                      key={item.id}
                      onClick={() => {
                        scrollToSection(item.href);
                        setIsMobileMenuOpen(false);
                      }}
                      className="w-full text-left text-white/90 hover:text-yellow-400 transition-colors duration-300 font-bold py-4 px-4 rounded-sm hover:bg-white/5 border-b border-white/10 last:border-b-0 text-lg uppercase tracking-wide"
                    >
                      {item.label}
                    </button>
                  ))}
                </nav>

                <div className="border-t border-white/10 pt-6">
                  <div className="flex items-center space-x-2 text-sm text-white/80 mb-4">
                    <Phone className="h-4 w-4 text-yellow-400" />
                    <span>{mockData.casinoInfo.phone}</span>
                  </div>
                  <div className="flex items-center space-x-2 text-sm text-white/80 mb-6">
                    <MapPin className="h-4 w-4 text-yellow-400" />
                    <span>Oka, Québec</span>
                  </div>
                  <Button 
                    className="w-full bg-red-600 hover:bg-red-700 text-white font-semibold py-3 rounded-sm shadow-lg mb-4"
                    onClick={() => {
                      scrollToSection('#contact');
                      setIsMobileMenuOpen(false);
                    }}
                  >
                    {t('nav.reserve')}
                  </Button>
                  <Button 
                    variant="outline"
                    className="w-full border-2 border-yellow-400 text-yellow-400 hover:bg-yellow-400 hover:text-black font-semibold py-3 rounded-sm backdrop-blur-sm"
                    onClick={openLocation}
                  >
                    <MapPin className="h-4 w-4 mr-2" />
                    {t('nav.visit')}
                  </Button>
                </div>
              </div>
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </header>
    </>
  );
};

export default Header;