import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { 
  Plus, 
  Calendar, 
  DollarSign,
  Tag,
  CheckCircle,
  XCircle
} from 'lucide-react';

// Onglet Événements
export const EventsTab = ({ events, newEvent, setNewEvent, handleAddEvent }) => {
  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('fr-CA');
  };

  return (
    <div className="space-y-6">
      {/* Ajouter un événement */}
      <Card className="bg-gradient-to-br from-black/80 via-blue-950/40 to-black/80 border border-blue-500/20">
        <CardHeader>
          <CardTitle className="text-white flex items-center space-x-2">
            <Plus className="h-5 w-5 text-blue-400" />
            <span>Ajouter un nouvel événement</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleAddEvent} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Input
                placeholder="Titre de l'événement"
                value={newEvent.title}
                onChange={(e) => setNewEvent({...newEvent, title: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
                required
              />
              <select
                value={newEvent.category}
                onChange={(e) => setNewEvent({...newEvent, category: e.target.value})}
                className="bg-black/50 border border-white/20 text-white rounded-md px-3 py-2"
              >
                <option value="general">Général</option>
                <option value="spectacle">Spectacle</option>
                <option value="tournoi">Tournoi</option>
                <option value="soiree">Soirée thématique</option>
              </select>
            </div>
            
            <Textarea
              placeholder="Description de l'événement"
              value={newEvent.description}
              onChange={(e) => setNewEvent({...newEvent, description: e.target.value})}
              className="bg-black/50 border-white/20 text-white"
              rows={3}
              required
            />
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Input
                type="date"
                value={newEvent.date}
                onChange={(e) => setNewEvent({...newEvent, date: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
                required
              />
              <Input
                type="time"
                value={newEvent.time}
                onChange={(e) => setNewEvent({...newEvent, time: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
                required
              />
              <Input
                type="number"
                step="0.01"
                placeholder="Prix (optionnel)"
                value={newEvent.price}
                onChange={(e) => setNewEvent({...newEvent, price: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
              />
            </div>
            
            <Input
              placeholder="URL image (optionnel)"
              value={newEvent.image}
              onChange={(e) => setNewEvent({...newEvent, image: e.target.value})}
              className="bg-black/50 border-white/20 text-white"
            />
            
            <Button 
              type="submit"
              className="bg-gradient-to-r from-blue-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 text-white font-semibold"
            >
              <Plus className="h-4 w-4 mr-2" />
              Ajouter l'événement
            </Button>
          </form>
        </CardContent>
      </Card>

      {/* Liste des événements */}
      <Card className="bg-gradient-to-br from-black/80 via-blue-950/40 to-black/80 border border-blue-500/20">
        <CardHeader>
          <CardTitle className="text-white">Liste des événements</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {events.map((event) => (
              <div key={event.id} className="bg-black/50 rounded-lg p-4 border border-white/10">
                <div className="space-y-3">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-white font-semibold text-lg">{event.title}</h3>
                      <Badge className="bg-blue-600/20 text-blue-400 mt-1">
                        {event.category}
                      </Badge>
                    </div>
                    <Badge className={event.isActive ? 'bg-green-600/20 text-green-400' : 'bg-red-600/20 text-red-400'}>
                      {event.isActive ? 'Actif' : 'Inactif'}
                    </Badge>
                  </div>
                  <p className="text-white/80">{event.description}</p>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                    <div>
                      <span className="text-white/50">Date:</span>
                      <span className="text-white ml-2">{formatDate(event.date)}</span>
                    </div>
                    <div>
                      <span className="text-white/50">Heure:</span>
                      <span className="text-white ml-2">{event.time}</span>
                    </div>
                    {event.price && (
                      <div>
                        <span className="text-white/50">Prix:</span>
                        <span className="text-white ml-2">{event.price}$</span>
                      </div>
                    )}
                    <div>
                      <span className="text-white/50">Créé:</span>
                      <span className="text-white ml-2">{formatDate(event.createdAt)}</span>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

// Onglet Promotions
export const PromotionsTab = ({ promotions, newPromotion, setNewPromotion, handleAddPromotion }) => {
  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('fr-CA');
  };

  return (
    <div className="space-y-6">
      {/* Ajouter une promotion */}
      <Card className="bg-gradient-to-br from-black/80 via-purple-950/40 to-black/80 border border-purple-500/20">
        <CardHeader>
          <CardTitle className="text-white flex items-center space-x-2">
            <Plus className="h-5 w-5 text-purple-400" />
            <span>Ajouter une nouvelle promotion</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleAddPromotion} className="space-y-4">
            <Input
              placeholder="Titre de la promotion"
              value={newPromotion.title}
              onChange={(e) => setNewPromotion({...newPromotion, title: e.target.value})}
              className="bg-black/50 border-white/20 text-white"
              required
            />
            
            <Textarea
              placeholder="Description de la promotion"
              value={newPromotion.description}
              onChange={(e) => setNewPromotion({...newPromotion, description: e.target.value})}
              className="bg-black/50 border-white/20 text-white"
              rows={3}
              required
            />
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-white/80 text-sm">Date de début</label>
                <Input
                  type="date"
                  value={newPromotion.startDate}
                  onChange={(e) => setNewPromotion({...newPromotion, startDate: e.target.value})}
                  className="bg-black/50 border-white/20 text-white mt-1"
                  required
                />
              </div>
              <div>
                <label className="text-white/80 text-sm">Date de fin</label>
                <Input
                  type="date"
                  value={newPromotion.endDate}
                  onChange={(e) => setNewPromotion({...newPromotion, endDate: e.target.value})}
                  className="bg-black/50 border-white/20 text-white mt-1"
                  required
                />
              </div>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Input
                type="number"
                placeholder="Réduction (%)"
                value={newPromotion.discountPercent}
                onChange={(e) => setNewPromotion({...newPromotion, discountPercent: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
              />
              <Input
                type="number"
                step="0.01"
                placeholder="Montant fixe ($)"
                value={newPromotion.discountAmount}
                onChange={(e) => setNewPromotion({...newPromotion, discountAmount: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
              />
              <Input
                placeholder="Code promo"
                value={newPromotion.code}
                onChange={(e) => setNewPromotion({...newPromotion, code: e.target.value})}
                className="bg-black/50 border-white/20 text-white"
              />
            </div>
            
            <Input
              placeholder="URL image (optionnel)"
              value={newPromotion.image}
              onChange={(e) => setNewPromotion({...newPromotion, image: e.target.value})}
              className="bg-black/50 border-white/20 text-white"
            />
            
            <Button 
              type="submit"
              className="bg-gradient-to-r from-purple-500 to-purple-600 hover:from-purple-600 hover:to-purple-700 text-white font-semibold"
            >
              <Plus className="h-4 w-4 mr-2" />
              Ajouter la promotion
            </Button>
          </form>
        </CardContent>
      </Card>

      {/* Liste des promotions */}
      <Card className="bg-gradient-to-br from-black/80 via-purple-950/40 to-black/80 border border-purple-500/20">
        <CardHeader>
          <CardTitle className="text-white">Liste des promotions</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {promotions.map((promotion) => (
              <div key={promotion.id} className="bg-black/50 rounded-lg p-4 border border-white/10">
                <div className="space-y-3">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-white font-semibold text-lg">{promotion.title}</h3>
                      {promotion.code && (
                        <Badge className="bg-yellow-600/20 text-yellow-400 mt-1">
                          Code: {promotion.code}
                        </Badge>
                      )}
                    </div>
                    <Badge className={promotion.isActive ? 'bg-green-600/20 text-green-400' : 'bg-red-600/20 text-red-400'}>
                      {promotion.isActive ? 'Active' : 'Inactive'}
                    </Badge>
                  </div>
                  <p className="text-white/80">{promotion.description}</p>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                    <div>
                      <span className="text-white/50">Début:</span>
                      <span className="text-white ml-2">{formatDate(promotion.startDate)}</span>
                    </div>
                    <div>
                      <span className="text-white/50">Fin:</span>
                      <span className="text-white ml-2">{formatDate(promotion.endDate)}</span>
                    </div>
                    {promotion.discountPercent && (
                      <div>
                        <span className="text-white/50">Réduction:</span>
                        <span className="text-white ml-2">{promotion.discountPercent}%</span>
                      </div>
                    )}
                    {promotion.discountAmount && (
                      <div>
                        <span className="text-white/50">Montant:</span>
                        <span className="text-white ml-2">{promotion.discountAmount}$</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};