import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Label } from './ui/label';
import { Lock, User, AlertCircle } from 'lucide-react';

const AdminLogin = ({ onLogin }) => {
  const [credentials, setCredentials] = useState({
    username: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Simple authentication (you can replace with your own system)
    if (credentials.username === 'admin' && credentials.password === 'casino2024') {
      localStorage.setItem('adminAuth', 'true');
      onLogin(true);
    } else {
      setError('Nom d\'utilisateur ou mot de passe incorrect');
    }
    setIsLoading(false);
  };

  const handleChange = (e) => {
    setCredentials({
      ...credentials,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-red-950/30 to-black flex items-center justify-center p-4">
      <Card className="w-full max-w-md bg-gradient-to-br from-black/90 via-red-950/40 to-black/90 backdrop-blur-sm border border-yellow-500/20">
        <CardHeader className="text-center">
          <div className="mx-auto w-16 h-16 bg-gradient-to-br from-yellow-400 to-red-500 rounded-full flex items-center justify-center mb-4">
            <Lock className="h-8 w-8 text-black" />
          </div>
          <CardTitle className="text-2xl text-white">
            Administration Casino TRIPLE 7
          </CardTitle>
          <p className="text-white/70">Connexion sécurisée</p>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            {error && (
              <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-3 flex items-center space-x-2">
                <AlertCircle className="h-4 w-4 text-red-400" />
                <span className="text-red-200 text-sm">{error}</span>
              </div>
            )}
            
            <div>
              <Label htmlFor="username" className="text-white/80 flex items-center space-x-2 mb-2">
                <User className="h-4 w-4" />
                <span>Nom d'utilisateur</span>
              </Label>
              <Input
                id="username"
                name="username"
                type="text"
                value={credentials.username}
                onChange={handleChange}
                className="bg-black/50 border-white/20 text-white focus:border-yellow-400"
                required
                disabled={isLoading}
              />
            </div>

            <div>
              <Label htmlFor="password" className="text-white/80 flex items-center space-x-2 mb-2">
                <Lock className="h-4 w-4" />
                <span>Mot de passe</span>
              </Label>
              <Input
                id="password"
                name="password"
                type="password"
                value={credentials.password}
                onChange={handleChange}
                className="bg-black/50 border-white/20 text-white focus:border-yellow-400"
                required
                disabled={isLoading}
              />
            </div>

            <Button
              type="submit"
              disabled={isLoading}
              className="w-full bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-semibold py-2 rounded-lg transition-all duration-300"
            >
              {isLoading ? 'Connexion...' : 'Se connecter'}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
};

export default AdminLogin;