import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { 
  MapPin, 
  Phone, 
  Mail, 
  Clock,
  Navigation,
  Car,
  Bus,
  Info,
  Send,
  CheckCircle,
  User,
  MessageSquare,
  Loader2,
  AlertCircle
} from 'lucide-react';
import { mockData } from '../mockData';
import { useLanguage } from '../context/LanguageContext';

const Contact = () => {
  const { t } = useLanguage();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: ''
  });
  const [formSubmitted, setFormSubmitted] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState('');

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    // Clear error when user starts typing
    if (submitError) {
      setSubmitError('');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitError('');

    try {
      // Using Formspree
      const response = await fetch('https://formspree.io/f/xpwyyjon', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: formData.name,
          email: formData.email,
          phone: formData.phone || '',
          message: formData.message
        })
      });

      if (response.ok) {
        setFormSubmitted(true);
        // Reset form
        setFormData({
          name: '',
          email: '',
          phone: '',
          message: ''
        });
        
        // Hide success message after 5 seconds
        setTimeout(() => setFormSubmitted(false), 5000);
      } else {
        throw new Error('Form submission failed');
      }
    } catch (error) {
      console.error('Error submitting contact form:', error);
      setSubmitError('Une erreur est survenue. Veuillez réessayer.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const openLocation = () => {
    window.open(mockData.casinoInfo.googleMapsUrl, '_blank');
  };

  return (
    <section id="contact" className="py-6 lg:py-12 bg-gradient-to-br from-black via-red-950/30 to-yellow-900/20">
      <div className="container mx-auto px-4">
        {/* Section Header Spectaculaire */}
        <div className="text-center mb-8">
          <div className="inline-block bg-gradient-to-r from-yellow-400 via-yellow-500 to-red-500 text-transparent bg-clip-text mb-6">
            <h2 className="text-5xl md:text-7xl font-black tracking-tight drop-shadow-2xl">
              📍 {t('contact.title').toUpperCase()} 📍
            </h2>
          </div>
          <div className="mb-6">
            <span className="text-4xl md:text-6xl font-bold text-white drop-shadow-lg">
              {t('contact.badge')}
            </span>
          </div>
          <div className="h-2 w-40 bg-gradient-to-r from-yellow-400 to-red-500 mx-auto rounded-full mb-6"></div>
          <p className="text-xl md:text-2xl text-white font-bold max-w-4xl mx-auto drop-shadow-lg">
            {t('contact.description')}
          </p>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-2 gap-12">
          {/* Google Maps & Contact Form */}
          <div className="space-y-8">
            {/* Google Maps Embed Réel */}
            <Card className="bg-gradient-to-br from-black/80 via-red-950/40 to-black/80 backdrop-blur-sm border-2 border-yellow-500/30 hover:border-yellow-400/60 transition-all duration-300 overflow-hidden shadow-2xl hover:shadow-yellow-500/20">
              <CardContent className="p-0">
                <div className="relative h-96">
                  {/* Google Maps Embed */}
                  <iframe 
                    src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2798.063245190227!2d-74.1189173240838!3d45.46852987107412!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc9352341fbb02f%3A0xd2ee173d10a0ef5c!2sTriple%207%20Casino!5e0!3m2!1sen!2sca!4v1759807748906!5m2!1sen!2sca"
                    width="100%" 
                    height="100%" 
                    style={{border: 0}} 
                    allowFullScreen={true}
                    loading="lazy" 
                    referrerPolicy="no-referrer-when-downgrade"
                    title="Casino TRIPLE 7 - Localisation"
                    className="w-full h-full rounded-lg"
                  />
                  
                  {/* Info overlay en bas */}
                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <h3 className="text-white font-black text-lg drop-shadow-lg">📍 Casino TRIPLE 7</h3>
                        <p className="text-white/90 text-sm font-medium">{mockData.casinoInfo.address}</p>
                      </div>
                      <Button 
                        className="bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-bold px-4 py-2 rounded-xl shadow-xl transition-all duration-300 transform hover:scale-105"
                        onClick={openLocation}
                      >
                        <MapPin className="h-4 w-4 mr-2" />
                        {t('footer.viewMap')}
                      </Button>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Contact Form */}
          <div className="space-y-8">
            <Card className="bg-gradient-to-br from-black/80 via-red-950/40 to-black/80 backdrop-blur-sm border border-yellow-500/20">
              <CardHeader>
                <CardTitle className="text-2xl text-white flex items-center space-x-3">
                  <MessageSquare className="h-7 w-7 text-yellow-400" />
                  <span>{t('contact.form.title')}</span>
                </CardTitle>
                <p className="text-white/70">{t('contact.form.subtitle')}</p>
              </CardHeader>
              <CardContent>
                {formSubmitted ? (
                  <div className="text-center py-8">
                    <CheckCircle className="h-16 w-16 text-green-400 mx-auto mb-4" />
                    <h3 className="text-xl font-bold text-white mb-2">{t('contact.form.success')}</h3>
                    <p className="text-white/80">{t('contact.form.successDesc')}</p>
                  </div>
                ) : (
                  <form onSubmit={handleSubmit} className="space-y-6">
                    {submitError && (
                      <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-4 flex items-start space-x-3">
                        <AlertCircle className="h-5 w-5 text-red-400 mt-0.5 flex-shrink-0" />
                        <p className="text-red-200 text-sm">{submitError}</p>
                      </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-white/80 text-sm font-medium mb-2">
                          <User className="h-4 w-4 inline mr-2" />
                          Nom complet *
                        </label>
                        <Input
                          type="text"
                          name="name"
                          value={formData.name}
                          onChange={handleInputChange}
                          className="bg-black/50 border-white/20 text-white placeholder:text-white/50 focus:border-yellow-400"
                          placeholder="Votre nom"
                          required
                          disabled={isSubmitting}
                        />
                      </div>

                      <div>
                        <label className="block text-white/80 text-sm font-medium mb-2">
                          <Mail className="h-4 w-4 inline mr-2" />
                          {t('contact.form.email')} *
                        </label>
                        <Input
                          type="email"
                          name="email"
                          value={formData.email}
                          onChange={handleInputChange}
                          className="bg-black/50 border-white/20 text-white placeholder:text-white/50 focus:border-yellow-400"
                          placeholder={t('contact.form.emailPlaceholder')}
                          required
                          disabled={isSubmitting}
                        />
                      </div>
                    </div>

                    <div>
                      <label className="block text-white/80 text-sm font-medium mb-2">
                        <Phone className="h-4 w-4 inline mr-2" />
                        {t('contact.form.phone')}
                      </label>
                      <Input
                        type="tel"
                        name="phone"
                        value={formData.phone}
                        onChange={handleInputChange}
                        className="bg-black/50 border-white/20 text-white placeholder:text-white/50 focus:border-yellow-400"
                        placeholder="(450) 000-0000"
                        disabled={isSubmitting}
                      />
                    </div>

                    <div>
                      <label className="block text-white/80 text-sm font-medium mb-2">
                        {t('contact.form.message')} *
                      </label>
                      <Textarea
                        name="message"
                        value={formData.message}
                        onChange={handleInputChange}
                        placeholder={t('contact.form.messagePlaceholder')}
                        className="bg-black/50 border-white/20 text-white placeholder:text-white/50 focus:border-yellow-400 min-h-32"
                        required
                        disabled={isSubmitting}
                      />
                    </div>

                    <Button 
                      type="submit"
                      className="w-full bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-bold py-4 rounded-xl shadow-xl transition-all duration-300 transform hover:scale-105"
                      disabled={isSubmitting}
                    >
                      {isSubmitting ? t('contact.form.sending') : t('contact.form.send')}
                    </Button>
                  </form>
                )}
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Bottom Info Cards - Contact, Accès, Horaires */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-12">
          {/* Contact Info */}
          <Card className="bg-gradient-to-br from-black/80 via-red-950/40 to-black/80 backdrop-blur-sm border border-red-500/20">
            <CardHeader>
              <CardTitle className="text-white flex items-center space-x-3">
                <Phone className="h-6 w-6 text-red-400" />
                <span>{t('contact.cards.contact')}</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <p className="text-white/60 text-sm">{t('contact.form.phone')}</p>
                <a 
                  href={`tel:${mockData.casinoInfo.phone}`}
                  className="text-white font-semibold text-lg hover:text-yellow-400 transition-colors duration-300 cursor-pointer"
                >
                  {mockData.casinoInfo.phone}
                </a>
              </div>
              <div>
                <p className="text-white/60 text-sm">{t('contact.form.email')}</p>
                <p className="text-white font-semibold">{mockData.casinoInfo.email}</p>
              </div>
            </CardContent>
          </Card>

          {/* Access Info */}
          <Card className="bg-gradient-to-br from-black/80 via-yellow-950/40 to-black/80 backdrop-blur-sm border border-yellow-500/20">
            <CardHeader>
              <CardTitle className="text-white flex items-center space-x-3">
                <Car className="h-6 w-6 text-yellow-400" />
                <span>{t('contact.cards.access')}</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center space-x-2">
                <Car className="h-5 w-5 text-yellow-400" />
                <span className="text-white/80">{t('contact.cards.freeParking')}</span>
              </div>
              <div className="flex items-center space-x-2">
                <Bus className="h-5 w-5 text-yellow-400" />
                <span className="text-white/80">{t('contact.cards.publicTransport')}</span>
              </div>
              <div className="flex items-center space-x-2">
                <Info className="h-5 w-5 text-yellow-400" />
                <span className="text-white/80">{t('contact.cards.wheelchair')}</span>
              </div>
            </CardContent>
          </Card>

          {/* Opening Hours */}
          <Card className="bg-gradient-to-br from-black/80 via-yellow-950/40 to-black/80 backdrop-blur-sm border border-yellow-500/20">
            <CardHeader>
              <CardTitle className="text-white flex items-center space-x-3">
                <Clock className="h-6 w-6 text-yellow-400" />
                <span>{t('contact.cards.hours')}</span>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {Object.entries(mockData.openingHours).map(([day, hours]) => (
                  <div key={day} className="flex justify-between items-center py-1">
                    <span className="text-white/80 capitalize text-sm">{t(`days.${day}`)}</span>
                    <span className="text-yellow-400 font-semibold text-sm">{hours}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </section>
  );
};

export default Contact;