import React, { useState, useEffect } from 'react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { ChevronLeft, ChevronRight, Trophy, Calendar, DollarSign } from 'lucide-react';
import { Button } from './ui/button';
import { useLanguage } from '../context/LanguageContext';
import axios from 'axios';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;

const WinnersCarousel = () => {
  const { t, language } = useLanguage();
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isAutoPlay, setIsAutoPlay] = useState(true);
  const [selectedWinner, setSelectedWinner] = useState(null);
  const [winners, setWinners] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  // Fetch winners from backend
  useEffect(() => {
    const fetchWinners = async () => {
      try {
        const response = await axios.get(`${BACKEND_URL}/api/winners`);
        setWinners(response.data.winners || []);
      } catch (error) {
        console.error('Error fetching winners:', error);
        setWinners([]);
      } finally {
        setIsLoading(false);
      }
    };

    fetchWinners();
  }, []);

  useEffect(() => {
    if (!isAutoPlay) return;

    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % winners.length);
    }, 4000);

    return () => clearInterval(timer);
  }, [isAutoPlay, winners.length]);

  const goToSlide = (index) => {
    setCurrentSlide(index);
  };

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % winners.length);
  };

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + winners.length) % winners.length);
  };

  const formatAmount = (amount) => {
    const locale = language === 'en' ? 'en-CA' : 'fr-CA';
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: 'CAD'
    }).format(amount);
  };

  const formatDate = (dateString) => {
    const locale = language === 'en' ? 'en-CA' : 'fr-CA';
    return new Date(dateString).toLocaleDateString(locale, {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  };

  // Show loading or empty state
  if (isLoading) {
    return (
      <section id="winners" className="py-6 lg:py-12 bg-gradient-to-br from-black via-red-950/30 to-black">
        <div className="container mx-auto px-4 text-center">
          <p className="text-white text-xl">Chargement des gagnants...</p>
        </div>
      </section>
    );
  }

  if (winners.length === 0) {
    return (
      <section id="winners" className="py-6 lg:py-12 bg-gradient-to-br from-black via-red-950/30 to-black">
        <div className="container mx-auto px-4 text-center">
          <h2 className="text-4xl font-bold text-white mb-4">{t('winners.title')}</h2>
          <p className="text-white/70">Aucun gagnant pour le moment. Revenez bientôt!</p>
        </div>
      </section>
    );
  }

  return (
    <section id="winners" className="py-6 lg:py-12 bg-gradient-to-br from-black via-red-950/30 to-black">
      <div className="container mx-auto px-4">
        {/* Section Header */}
        <div className="text-center mb-8">
          <div className="inline-block bg-gradient-to-r from-yellow-400 via-yellow-500 to-red-500 text-transparent bg-clip-text mb-6">
            <h2 className="text-5xl md:text-7xl font-black tracking-tight drop-shadow-2xl">
              {t('winners.badge')}
            </h2>
          </div>
          <div className="mb-6">
            <span className="text-4xl md:text-6xl font-bold text-white drop-shadow-lg">
              {t('winners.title')}
            </span>
          </div>
          <p className="text-xl text-white/90 max-w-3xl mx-auto font-medium">
            {t('winners.description')}
          </p>
        </div>

        {/* Winners Container */}
        <div className="max-w-6xl mx-auto">
          {/* Desktop: Compact Cards Layout */}
          <div className="hidden lg:block">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {winners.map((winner, index) => (
                <Card key={winner.id} className="bg-gradient-to-br from-black via-gray-900/90 to-black backdrop-blur-sm border-2 border-yellow-500/30 hover:border-yellow-400/60 transition-all duration-300 transform hover:scale-105 shadow-2xl hover:shadow-yellow-500/20">
                  <CardContent className="p-6">
                    <div className="text-center space-y-4">
                      {/* Winner Photo - Plus grande */}
                      <div className="relative mx-auto w-fit">
                        <div 
                          className="w-48 h-48 rounded-lg overflow-hidden border-4 border-yellow-400 shadow-xl shadow-yellow-500/25 cursor-pointer transition-transform duration-300 hover:scale-105"
                          onClick={() => setSelectedWinner(winner)}
                        >
                          <img 
                            src={winner.photo} 
                            alt={winner.name}
                            className="w-full h-full object-cover"
                          />
                        </div>
                        <div className="absolute -top-2 -right-2 bg-yellow-400 rounded-full p-2 shadow-lg">
                          <Trophy className="h-5 w-5 text-black" />
                        </div>
                      </div>

                      {/* Winner Info */}
                      <div>
                        <h3 className="text-lg font-bold text-white mb-2">{winner.name}</h3>
                        <p className="text-2xl font-black text-transparent bg-gradient-to-r from-yellow-400 via-yellow-300 to-red-400 bg-clip-text drop-shadow-lg mb-2">
                          {formatAmount(winner.amount)}
                        </p>
                        <div className="text-white/80 text-sm space-y-1">
                          <div className="flex items-center justify-center gap-1">
                            <Trophy className="h-4 w-4 text-red-400" />
                            <span>{winner.game}</span>
                          </div>
                          <div className="flex items-center justify-center gap-1">
                            <Calendar className="h-4 w-4 text-yellow-400" />
                            <span>{formatDate(winner.date)}</span>
                          </div>
                        </div>
                      </div>

                      {/* View Button */}
                      <Button 
                        onClick={() => setSelectedWinner(winner)}
                        className="w-full bg-gradient-to-r from-yellow-600 to-yellow-700 hover:from-yellow-700 hover:to-yellow-800 text-black font-bold py-2 rounded-lg shadow-lg transition-all duration-300"
                      >
                        👁️ {t('winners.viewDetails')}
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>

          {/* Mobile: Horizontal Carousel */}
          <div className="lg:hidden relative">
            <div 
              className="flex transition-transform duration-500 ease-in-out"
              style={{ transform: `translateX(-${currentSlide * 100}%)` }}
              onMouseEnter={() => setIsAutoPlay(false)}
              onMouseLeave={() => setIsAutoPlay(true)}
            >
              {winners.map((winner, index) => (
                <div key={winner.id} className="w-full flex-shrink-0 px-4">
                  <Card className="bg-gradient-to-br from-black via-gray-900/90 to-black backdrop-blur-sm border-2 border-yellow-500/30 hover:border-yellow-400/60 transition-all duration-300 transform hover:scale-105 shadow-2xl hover:shadow-yellow-500/20">
                    <CardContent className="p-6">
                      <div className="text-center">
                        {/* Winner Photo - Grande et cliquable */}
                        <div 
                          className="relative mx-auto mb-4 cursor-pointer"
                          onClick={() => setSelectedWinner(winner)}
                        >
                          <div className="w-40 h-40 rounded-lg overflow-hidden border-4 border-yellow-400 shadow-2xl shadow-yellow-500/25 mx-auto transition-transform duration-300 hover:scale-105">
                            <img 
                              src={winner.photo} 
                              alt={winner.name}
                              className="w-full h-full object-cover"
                            />
                          </div>
                          <div className="absolute -top-2 -right-2 bg-yellow-400 rounded-full p-2 shadow-lg">
                            <Trophy className="h-6 w-6 text-black" />
                          </div>
                        </div>

                        {/* Amount Display - Encadré doré seulement */}
                        <div className="bg-gradient-to-br from-yellow-500/20 via-yellow-400/10 to-red-500/20 rounded-2xl p-6 border-2 border-yellow-500/40 shadow-lg backdrop-blur-sm">
                          <h3 className="text-2xl font-bold text-white mb-2">{winner.name}</h3>
                          <p className="text-sm text-yellow-300 font-bold mb-2 tracking-wide">💰 {t('winners.winnings')} 💰</p>
                          <p className="text-3xl font-black text-transparent bg-gradient-to-r from-yellow-400 via-yellow-300 to-red-400 bg-clip-text drop-shadow-lg mb-2">
                            {formatAmount(winner.amount)}
                          </p>
                          <div className="text-white/80 text-sm mb-2">
                            <div className="flex items-center justify-center gap-1 mb-1">
                              <Trophy className="h-4 w-4 text-red-400" />
                              <span>{winner.game}</span>
                            </div>
                            <div className="flex items-center justify-center gap-1">
                              <Calendar className="h-4 w-4 text-yellow-400" />
                              <span>{formatDate(winner.date)}</span>
                            </div>
                          </div>
                          <div className="flex justify-center">
                            <div className="bg-red-600 text-white text-xs font-bold px-3 py-1 rounded-full">
                              {t('winners.jackpot')}
                            </div>
                          </div>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>
              ))}
            </div>

            {/* Navigation Arrows - Mobile Only */}
            <Button
              variant="outline"
              size="icon"
              className="absolute left-2 top-1/2 transform -translate-y-1/2 bg-black/70 border-yellow-400/50 text-yellow-400 hover:bg-yellow-400 hover:text-black backdrop-blur-sm rounded-full transition-all duration-300 z-10 shadow-xl"
              onClick={prevSlide}
            >
              <ChevronLeft className="h-6 w-6" />
            </Button>
            
            <Button
              variant="outline"
              size="icon"
              className="absolute right-2 top-1/2 transform -translate-y-1/2 bg-black/70 border-yellow-400/50 text-yellow-400 hover:bg-yellow-400 hover:text-black backdrop-blur-sm rounded-full transition-all duration-300 z-10 shadow-xl"
              onClick={nextSlide}
            >
              <ChevronRight className="h-6 w-6" />
            </Button>

            {/* Dots Indicator - Mobile Only */}
            <div className="flex justify-center mt-8 space-x-3">
              {winners.map((_, index) => (
                <button
                  key={index}
                  className={`w-3 h-3 rounded-full transition-all duration-300 ${
                    index === currentSlide 
                      ? 'bg-gradient-to-r from-yellow-400 to-red-500 w-8' 
                      : 'bg-white/30 hover:bg-white/50'
                  }`}
                  onClick={() => goToSlide(index)}
                />
              ))}
            </div>
          </div>
        </div>

        {/* CTA Section */}
        <div className="text-center mt-8">
          <div className="mb-8">
            <p className="text-2xl md:text-3xl text-white font-bold mb-4 drop-shadow-lg">
              {t('winners.nextWinner')}
            </p>
          </div>
          <Button 
            size="lg"
            className="bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-black text-xl px-12 py-6 rounded-xl shadow-2xl transition-all duration-300 transform hover:scale-105 hover:shadow-red-600/25 border-2 border-red-500/50"
            onClick={() => {
              const element = document.querySelector('#contact');
              if (element) {
                element.scrollIntoView({ behavior: 'smooth' });
              }
            }}
          >
            🎰 {t('winners.tryLuck').toUpperCase()} 🎰
          </Button>
        </div>
      </div>

      {/* Modal pour voir le gagnant */}
      {selectedWinner && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-gradient-to-br from-black via-gray-900 to-black border-2 border-yellow-500/40 rounded-xl p-6 max-w-md w-full mx-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-2xl font-bold text-white">🏆 {t('winners.winner')}</h3>
              <button
                onClick={() => setSelectedWinner(null)}
                className="text-white/60 hover:text-white transition-colors"
              >
                ✕
              </button>
            </div>
            
            <div className="text-center">
              <div className="w-64 h-64 rounded-lg overflow-hidden border-4 border-yellow-400 shadow-2xl mx-auto mb-4">
                <img 
                  src={selectedWinner.photo} 
                  alt={selectedWinner.name}
                  className="w-full h-full object-cover"
                />
              </div>
              
              <h4 className="text-xl font-bold text-white mb-2">{selectedWinner.name}</h4>
              <p className="text-3xl font-black text-transparent bg-gradient-to-r from-yellow-400 to-red-500 bg-clip-text mb-2">
                {formatAmount(selectedWinner.amount)}
              </p>
              <p className="text-white/80 mb-1">{selectedWinner.game}</p>
              <p className="text-white/60 text-sm">{formatDate(selectedWinner.date)}</p>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default WinnersCarousel;